// Copy to apps/<app>/.dependency-cruiser.cjs. Run with cwd = apps/<app>.
// Domain root: NestJS — 'src' (default), Angular — 'src/app' (FMA_SRC_ROOT=src/app); a Nest app generated by
// @nx/nest keeps domains in 'src/app' too. Other settings (all optional, set by arch-check from its flags):
//   FMA_NON_DOMAINS=common,config,database  extra root folders that are infrastructure, not domains
//                                           (a domain may import their files directly; they are not checked as domains)
//   FMA_APP=web                             Angular naming (set by arch-check for --web): the role of a file is the end of its
//                                           name (cart-state.ts, cart-api.ts, cart-page.ts, cart-mapper.ts, cart-rules.ts; the
//                                           dotted form cart.state.ts is accepted too) and a folder of a domain without index.ts is
//                                           a presentational component folder (cart-badge/). Without it the NestJS naming applies
//                                           (cart.service.ts) and the legacy ui/ folder is recognized.
//   FMA_INFRA_DIRS=src/app/core,src/app/shared  folders outside the domain root (paths from cwd) that must not import domains
//                                           (rule infra-no-domain), e.g. core/ next to an Angular features/ root
//   FMA_TSCONFIG=tsconfig.app.json          tsconfig used to resolve aliases (Nx services have no tsconfig.json)
// Regular expressions avoid nested quantifiers: dependency-cruiser considers them unsafe.
const fs = require('node:fs');
const path = require('node:path');

const ROOT = process.env.FMA_SRC_ROOT || 'src';
const INFRA_DIRS = (process.env.FMA_INFRA_DIRS || '')
  .split(',')
  .map((x) => x.trim().replace(/\/+$/, ''))
  .filter(Boolean);
const TSCONFIG = process.env.FMA_TSCONFIG || 'tsconfig.json';
const escape = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const EXTRA_NON_DOMAINS = (process.env.FMA_NON_DOMAINS || '')
  .split(',')
  .map((x) => x.trim())
  .filter(Boolean);
const NON_DOMAINS = new Set(['shared', 'contracts', ...EXTRA_NON_DOMAINS]);
const NON_DOMAIN_ALT = [...NON_DOMAINS].map(escape).join('|');
const TS = '\\.tsx?$';
const INDEX = `/index${TS}`;
const NPM_FRAMEWORKS = '(^|node_modules/)(@nestjs|@angular|typeorm|@prisma|drizzle-orm|rxjs)';
const NPM_ORM = '(^|node_modules/)(typeorm|@nestjs/typeorm|@prisma|drizzle-orm|mongoose)';

const dirs = (p) =>
  fs.existsSync(p) ? fs.readdirSync(p, { withFileTypes: true }).filter((d) => d.isDirectory()) : [];

// The rich tier = the module has a domain/ folder (even an empty one). Domains and their _submodules are considered.
const richModules = [];
for (const d of dirs(ROOT).filter((x) => !NON_DOMAINS.has(x.name))) {
  if (fs.existsSync(path.join(ROOT, d.name, 'domain'))) richModules.push(d.name);
  for (const sub of dirs(path.join(ROOT, d.name)).filter((x) => x.name.startsWith('_'))) {
    if (fs.existsSync(path.join(ROOT, d.name, sub.name, 'domain')))
      richModules.push(`${d.name}/${sub.name}`);
  }
}

const WEB = process.env.FMA_APP === 'web';
// A role by file name: `[.-]` in Angular (cart-state.ts and cart.state.ts), `.` otherwise (cart.service.ts).
const role = (names) => (WEB ? `[.-](${names})\\.ts$` : `\\.(${names})\\.ts$`);

// Angular: a folder of a domain (or of an internal _submodule) without index.ts is a presentational component
// folder named by its subject (cart-badge/), not by its code type. A folder with index.ts is a module.
const componentFolders = [];
const collectComponentFolders = (rel) => {
  for (const d of dirs(path.join(ROOT, rel))) {
    if (d.name === 'domain') continue;
    const sub = `${rel}/${d.name}`;
    const isModule = ['index.ts', 'index.tsx'].some((f) => fs.existsSync(path.join(ROOT, sub, f)));
    if (d.name.startsWith('_') || isModule) collectComponentFolders(sub);
    else componentFolders.push(`^${ROOT}/${escape(sub)}/`);
  }
};
if (WEB) {
  for (const d of dirs(ROOT).filter((x) => !NON_DOMAINS.has(x.name)))
    collectComponentFolders(d.name);
}

// ui = routed pages, components in component folders and the legacy ui/ folder.
const UI_DIRS = [`^${ROOT}/[^/]+/ui/`, `^${ROOT}/[^/]+/.*/ui/`, ...componentFolders];
const PAGE = `^${ROOT}/[^/]+/.*${role('page')}`;
const STATE = `^${ROOT}/[^/]+/.*${role('state')}`;
const DOMAIN_DIRS = [`^${ROOT}/[^/]+/domain/`, `^${ROOT}/[^/]+/.*/domain/`];

module.exports = {
  forbidden: [
    {
      name: 'no-circular',
      severity: 'error',
      comment:
        'Cycles between modules are forbidden (FMA). Two-way ORM relations between the entities of one domain are not reported (a cycle that goes through another file still is).',
      from: { pathNot: '\\.entity\\.ts$' },
      to: { circular: true },
    },
    {
      name: 'no-deep-import',
      severity: 'error',
      comment:
        'A neighbor is visible only through index.ts (FMA); a public submodule — through the parent index.',
      from: { path: `^${ROOT}/([^/]+)/`, pathNot: `^${ROOT}/(shared|contracts)/` },
      to: {
        path: `^${ROOT}/[^/]+/`,
        pathNot: [`^${ROOT}/$1/`, `^${ROOT}/(${NON_DOMAIN_ALT})/`, `^${ROOT}/[^/]+${INDEX}`],
      },
    },
    ...(INFRA_DIRS.length
      ? [
          {
            name: 'infra-no-domain',
            severity: 'error',
            comment:
              'Infrastructure folders outside the domain root (core, shared) do not import domains (FMA): the dependency goes from a feature to infrastructure.',
            from: { path: INFRA_DIRS.map((d) => `^${escape(d)}/`) },
            to: { path: `^${ROOT}/[^/]+/`, pathNot: `^${ROOT}/(${NON_DOMAIN_ALT})/` },
          },
        ]
      : []),
    {
      name: 'no-deep-shared',
      severity: 'error',
      comment: 'A shared segment is reachable only through its own index.ts (FMA).',
      from: { path: `^${ROOT}/`, pathNot: `^${ROOT}/shared/` },
      to: { path: `^${ROOT}/shared/[^/]+/`, pathNot: `^${ROOT}/shared/[^/]+${INDEX}` },
    },
    {
      name: 'shared-no-domain',
      severity: 'error',
      comment: 'shared does not depend on domains (FMA).',
      from: { path: `^${ROOT}/shared/` },
      to: { path: `^${ROOT}/[^/]+/`, pathNot: [`^${ROOT}/shared/`, `^${ROOT}/contracts/`] },
    },
    {
      name: 'child-no-parent',
      severity: 'error',
      comment:
        'A _submodule does not import files of its parent (FMA: child → parent is forbidden).',
      from: { path: `^${ROOT}/([^/]+)/_[^/]+/` },
      to: { path: `^${ROOT}/$1/[^/]+${TS}` },
    },
    {
      name: 'sibling-sub-deep',
      severity: 'error',
      comment: 'The _submodules of one domain reach each other only through index.ts.',
      from: { path: `^${ROOT}/([^/]+)/(_[^/]+)/` },
      to: {
        path: `^${ROOT}/$1/_[^/]+/`,
        pathNot: [`^${ROOT}/$1/$2/`, `^${ROOT}/$1/_[^/]+${INDEX}`],
      },
    },
    {
      name: 'ui-no-data',
      severity: 'error',
      comment: 'ui and page do not import api, model, repository or shared/data; only state (FMA).',
      from: { path: [...UI_DIRS, PAGE] },
      to: {
        path: [
          `^${ROOT}/[^/]+/.*${role(WEB ? 'api|model|mapper|rules|repository' : 'api|model|repository')}`,
          `^${ROOT}/shared/data/`,
        ],
      },
    },
    {
      name: 'lower-no-ui',
      severity: 'error',
      comment: 'api, model and repo do not import ui or state (FMA).',
      from: {
        path: [
          `^${ROOT}/[^/]+/.*\\.(api|model|repository|service|controller|consumer|resolver|worker|facade|policy)\\.ts$`,
          ...(WEB ? [`^${ROOT}/[^/]+/.*${role('api|mapper|rules')}`] : []),
        ],
      },
      to: { path: [...UI_DIRS, STATE, PAGE] },
    },
    {
      name: 'state-no-ui',
      severity: 'error',
      comment: 'state does not import ui or page (FMA).',
      from: { path: STATE },
      to: { path: [...UI_DIRS, PAGE] },
    },
    {
      name: 'service-no-controller',
      severity: 'error',
      comment:
        'service, facade and repository do not import controller, consumer or resolver (FMA).',
      from: { path: `^${ROOT}/[^/]+/.*\\.(service|facade|repository)\\.ts$` },
      to: { path: `^${ROOT}/[^/]+/.*\\.(controller|consumer|resolver)\\.ts$` },
    },
    {
      name: 'domain-pure',
      severity: 'error',
      comment: 'domain is pure TS: no framework, no ORM (FMA, rich tier).',
      from: { path: DOMAIN_DIRS },
      to: { path: NPM_FRAMEWORKS },
    },
    {
      name: 'domain-isolated',
      severity: 'error',
      comment: 'domain imports only its own domain/ and shared/util (FMA).',
      from: { path: `^${ROOT}/([^/]+)/domain/` },
      to: { path: `^${ROOT}/[^/]+/`, pathNot: [`^${ROOT}/$1/domain/`, `^${ROOT}/shared/util/`] },
    },
    {
      name: 'domain-isolated',
      severity: 'error',
      comment: 'The domain of a submodule imports only its own domain/ and shared/util (FMA).',
      from: { path: `^${ROOT}/([^/]+)/([^/]+)/domain/` },
      to: { path: `^${ROOT}/[^/]+/`, pathNot: [`^${ROOT}/$1/$2/domain/`, `^${ROOT}/shared/util/`] },
    },
    ...richModules.flatMap((m) => [
      {
        name: `rich-model-no-repo:${m}`,
        severity: 'error',
        comment: `In the rich module ${m}, service reaches storage only through a port (FMA).`,
        from: { path: `^${ROOT}/${m}/.*\\.service\\.ts$` },
        to: { path: `^${ROOT}/${m}/.*\\.repository\\.ts$` },
      },
      {
        name: `rich-model-no-orm:${m}`,
        severity: 'error',
        comment: `In the rich module ${m}, service does not use the ORM or entities directly (FMA).`,
        from: { path: `^${ROOT}/${m}/.*\\.service\\.ts$` },
        to: { path: [NPM_ORM, `^${ROOT}/${m}/.*\\.entity\\.ts$`] },
      },
    ]),
  ],
  options: {
    tsPreCompilationDeps: true,
    ...(fs.existsSync(TSCONFIG) ? { tsConfig: { fileName: TSCONFIG } } : {}),
    doNotFollow: { path: 'node_modules' },
    exclude: { path: '\\.(spec|test)\\.ts$' },
  },
};
